entries[392871] = { ["name"] = "Sengendes Gemetzel", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas Ziel markiert alle 5.2 Sek. seine aktuelle Position. Nach 1,5 Sek. explodiert die Markierung und fügt allen Spielercharakteren innerhalb von 5 Metern 187 Feuerschaden zu.\n\nZusätzlich bricht das Ziel mit ' Convo ' aus, wodurch es 50 Sek. lang alle 5.2 Sek. 0 Feuerschaden verursacht.\n\nJeder erfolgreiche Einsatz von ' Sengendes Gemetzel ' gewährt Kurog einen Stapel von ' Flammenvorherrschaft '." }
