entries[392944] = { ["name"] = "Drakonische Kürschnereiabhandlung", ["text"] = "Wirken in 3.5 sek. 2\nReagenzien:\nEifer des Handwerkers (10), Felszahnleder , Glitzerndes Pergament (5), Erweckte Erde , Brünierte Tinte\nEntdeckung:\nBei der Herstellung anderer drakonischer Abhandlungen\nBenötigt:\nSpezialisierung: Archivieren - Drakonische Abhandlungen\n\nDrakonische Kürschnereiabhandlung\nWird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Kürschnerei der Dracheninseln\n(25)\n\"Enthält Notizen über verschiedene Berufsgeheimnisse von Kürschnern. Kann nur einmal pro Woche gelesen werden.\"" }
