entries[392951] = { ["name"] = "Grenzenlose Erlösung", ["text"] = "'Heiliger Schock', 'Lichtblitz' und 'Heiliges Licht' verlängern die Dauer von 'Tyrs Errettung' bei Euch, wenn sie bei von 'Tyrs Errettung' betroffenen Zielen eingesetzt werden.\n\nHeiliger Schock : Verlängert den Effekt um 2.0 Sek.\n\nLichtblitz : Verlängert den Effekt um 4.0 Sek.\n\nHeiliges Licht : Verlängert den Effekt um 8.0 Sek.\n\n'Tyrs Errettung' kann bis zu einem Maximum von 40 Sek. verlängert werden." }
