entries[392958] = { ["name"] = "Glanz der Morgendämmerung", ["text"] = "'Tritt der aufgehenden Sonne' hat eine Chance in Höhe von 100% Eures Tempos, ein zweites Mal ausgelöst zu werden und dabei (100% der Angriffskraft) körperlichen Schaden zu verursachen sowie 1 Chi wiederherzustellen." }
