entries[392962] = { ["name"] = "Runenwaffe verstärken", ["text"] = "Runenwaffe verstärken\n30 Meter Reichweite\nSofort 30 Sek. Wiederaufladezeit 2 Charges\nRequires Death Knight (Frost) Entzieht Eurem Gegner Willen, um Eure Runenwaffe zu ermächtigen. Fügt (200% der Angriffskraft) Schattenfrostschaden sowie Gegnern in der Nähe verringerten Schaden zu und erlangt 40 Runenmacht und gewährt Euch 'Tötungsmaschine'." }
