entries[392985] = { ["name"] = "Donnerfaust", ["text"] = "Euer 'Schlag des Windlords' gewährt Euch 4 Stapel von 'Donnerfaust' sowie einen zusätzlichen Stapel für jeden getroffenen Gegner.\n\nAufladungen von 'Donnerfaust' entladen sich bei Nahkampfangriffen und verursachen dabei (161% der Angriffskraft) Naturschaden." }
entries[392986] = { ["name"] = "Xuens Band", ["text"] = "Der Schaden von 'Xuen den Weißen Tiger beschwören' ist um 30% erhöht und die Abklingzeit ist um 30 Sek. verringert." }
entries[392987] = { ["name"] = "Knochenmarkhopfen", ["text"] = "Erhöht den Schattenschaden oder die Heilung durch 'Knochenstaubgebräu' um 20.0% . Wenn 'Knochenstaubgebräu' Schattenschaden oder Heilung verursacht, verringert sich die Abklingzeit der Fähigkeit um 0.5 Sek." }
entries[392988] = { ["name"] = "Göttliches Abbild", ["text"] = "Beim Einsatz eines Segensworts wird ein Abbild eines Naaru an Eure Seite beschworen. Für die nächsten 9 Sek. imitiert der Naaru alle von Euch gewirkten Heilungs- oder Schadenszauber.\n\nWenn ein Abbild bereits beschworen wurde, wird dieses Abbild stattdessen verstärkt." }
