entries[392991] = { ["name"] = "Himmelweit", ["text"] = "Erhöht die Reichweite von 'Tigerklaue' auf 10 Meter und beim Einsatz springt Ihr sofort zum Ziel.\n\n'Tigerklaue' belegt das Ziel zusätzlich mit einem Effekt, der Eure kritische Trefferchance gegen das Ziel für 6 Sek. um 50% erhöht. Dieser Effekt kann pro Ziel nur einmal alle 1 Min. auftreten." }
