entries[392996] = { ["name"] = "Wildpilz", ["text"] = "40 Meter Reichweite\nSofort\nLässt an der Position des gegnerischen Ziels einen magischen Pilz wachsen. Nach 1 Sek. detoniert der Pilz, verursacht (254.4% der Zaubermacht) Naturschaden und anschließend im Verlauf von 10 Sek. zusätzlich (143.5% der Zaubermacht) Naturschaden. Betroffene Ziele werden um 50% verlangsamt.\n\nErzeugt abhängig von den getroffenen Zielen bis zu 20 Astrale Macht." }
