entries[393059] = { ["name"] = "Tausendbisspiranha", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nTausendbisspiranhas sind aggressive Süßwasserfische, die alles verschlingen, was ihnen in den Weg kommt!\n\nDiese Süßwasserschwärme findet man größtenteils in den großen Seen und weitverzweigten Flüssen der Dracheninseln.\n\nBesonders aktiv sind sie in Bereichen wie den Ebenen von Ohn'ahra und der Küste des Erwachens." }
entries[393060] = { ["name"] = "Himmelblauer Stachelfisch", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nHimmelblaue Stachelfische sind robuste stachelbedeckte Fische.\n\nDiese Salzwasserschwärme findet man gewöhnlich im Meer und damit verbundenen Gewässern.\n\nBesonders viele treiben sich in den Flussmündungen an der Küste des Erwachens herum." }
entries[393061] = { ["name"] = "Querflossen-Flügelrossfisch", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nQuerflossen-Flügelrossfische gleiten den Meeresboden entlang und schnellen hinauf, sobald sie etwas Schmackhaftes dort oben erwarten!\n\nDiese Salzwasserschwärme findet man gewöhnlich im Meer und damit verbundenen Gewässern.\n\nBesonders viele treiben sich in Iskaara im Azurblauen Gebirge herum." }
entries[393062] = { ["name"] = "Temporaler Drachenkopf", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nTemporale Drachenköpfe sind merkwürdige Fische, deren Schuppen so wirken, als würden sie alle paar Sekunden ein wenig vor und zurück versetzt. Finger weg vom scharfen Maul!\n\nDiese Süßwasserschwärme findet man größtenteils in den großen Seen und weitverzweigten Flüssen der Dracheninseln.\n\nBesonders viele treiben sich im Uktulutaltwasser der Küste des Erwachens herum." }
entries[393063] = { ["name"] = "Schuppenbauchmakrele", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSchuppenbauchmakrelen sind äußerst gewöhnliche Fische auf den Dracheninseln. Man kann sie überall leicht fangen.\n\nSelbst erfahrene Angler werfen sie regelmäßig zurück ins Wasser." }
entries[393064] = { ["name"] = "Inselfinnenschwertfisch", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nInselfinnenschwertfische sind scheue Wesen, deren Finne angeblich der Form der Dracheninseln ähnelt.\n\nMan findet sie überall auf den Inseln." }
entries[393065] = { ["name"] = "Schimmernder Schatz", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSchimmernde Schatzbecken findet man in allen Gewässern der Dracheninseln. Diese Becken enthalten unermessliche Schätze und ein jeder Angler erhofft, sie zu entdecken.\n\nAngeln in diesen Becken erhöht die Chance auf seltene Schätze erheblich." }
entries[393066] = { ["name"] = "Raureifflossenthunfisch", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nRaureifflossenthunfische sind große, fetthaltige Fische, die von einer dünnen Schutzschicht aus Eis umgeben sind. Die dicke Fettschicht schützt ihre Organe vor den eisigen Temperaturen.\n\nIhr findet diese Schwärme in besonders frostigen Bereichen der Dracheninseln.\n\nDie Tuskarr von Iskaara sind Experten, was den Fang dieser Fische betrifft." }
entries[393067] = { ["name"] = "Magmadrescher", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nMagmadrescher sind muskulöse Fische mit einer verhärteten Hülle aus verschiedenen Mineralien.\n\nIhr findet diese Schwärme in besonders heißen Bereichen der Dracheninseln.\n\nDie Tuskarr von Iskaara sind Experten im Fang dieser besonderen Fischart." }
entries[393070] = { ["name"] = "New Class Order" }
entries[393071] = { ["name"] = "Kraft aus der Widrigkeit", ["text"] = "Gewährt pro von 'Schild des Rächers' getroffenem Ziel 15 Sek. lang 3% Parieren." }
entries[393073] = { ["name"] = "PvP-Ausrüstung aufwerten", ["text"] = "Wirken in 3 sek.\nWertet einen Teil Ehren- oder Eroberungsausrüstung aus Saison 1 von Dragonflight auf den nächsten Rang auf.\n\nGegenstände können nicht den Rang überschreiten, den Euer höchster Rang im gewerteten PvP erlaubt." }
